+            RankListener {
+                rank: 4,
+                mode: HttpListenerMode::InheritedFd { fd: 5 },
+            },
+            RankListener {
+                rank: 5,
+                mode: HttpListenerMode::InheritedFd { fd: 6 },
+            },
+        ]
+    );
+    config.validate().unwrap();
+}
